/*
 * This file contains utility functions for QUnit/PhantomJS integration.
 * It ensures that global variables like QUnit, alert, and HTMLInspector are recognized
 * within the execution environment, particularly when running in PhantomJS.
 */

/*
 * The following function is responsible for parsing raw error objects
 * generated by HTMLInspector into a more structured and standardized format
 * suitable for reporting or further processing.
 *
 * @param {Array<Object>} errors - An array of raw error objects from HTMLInspector.
 * @returns {Array<Object>} An array of processed error objects, each with 'rule' and 'message' properties.
 */
function  _parseErrors ( errors )
{
  var
    results = [ ],  // Initialize an empty array to store the processed error objects.
    i       = 0,    // Loop counter, initialized to the first index.
    len;            // Variable to hold the total number of errors, for loop optimization.

  // Iterate over each error in the provided list.
  // The loop condition uses the pre-calculated length for efficiency.
  for ( len = errors.length;  i < len;  i++ )
  {
    results [ i ] =
    {
      // Extract the specific rule name that was violated.
      rule    :  errors [ i ].rule,
      // Extract the descriptive message associated with the error.
      message :  errors [ i ].message
    }; // End of error object literal.
  } // End of for loop.

  // Return the array containing all the newly structured error objects.
  return  results;
} // End of _parseErrors function definition.


/*
 * This function serves as the primary communication channel with the parent process,
 * typically PhantomJS. It serializes messages and sends them via the native `alert` mechanism,
 * which PhantomJS is configured to intercept.
 *
 * @param {...*} arguments - Any number of arguments to be sent as part of the message.
 *                           The first argument is usually a message type identifier.
 */
function   sendMessage   ( )
{
 var
    args = [ ].slice.call ( arguments ), // Convert the 'arguments' pseudo-array into a true Array object.
    msg  = args [ 0 ] // The first argument is typically the message type or identifier.
 ;

 // Check if the message indicates the completion of the HTML inspection process.
 if ( msg  ===  'htmlinspector.done' )
 {
  // If it is a 'done' message, the second argument is expected to be the raw errors.
  // These errors must be parsed into the standard format before being sent.
  args [ 1 ] = _parseErrors ( args [ 1 ] )
 ;
 }

 // Serialize the entire arguments array into a JSON string
 // and send it using the global 'alert' function.
 alert ( JSON.stringify ( args ) )
 ;
} // End of sendMessage function definition.

// Initiate the HTML inspection process using the HTMLInspector library.
// This is the entry point for the client-side inspection.
HTMLInspector.inspect (
 {
  // Define the callback function to be executed once the HTML inspection is fully complete.
  onComplete : function onComplete ( errors )
  {
   // Once inspection finishes, send a message to the parent process.
   // The message includes a 'htmlinspector.done' identifier and the array of detected errors.
   sendMessage (
    'htmlinspector.done', // Message type indicating completion.
    errors                // The raw errors reported by HTMLInspector.
   ) ;
  } // End of onComplete callback function.
 } // End of HTMLInspector configuration object.
) ; // End of HTMLInspector.inspect method call.